var idempotencyKey = ctx.Request.Headers["Idempotency-Key"].ToString();
if (string.IsNullOrWhiteSpace(idempotencyKey))
    return Results.BadRequest(new { error = "Idempotency-Key header is required" });

if (db.IdempotencyCache.TryGetValue(idempotencyKey, out var cached) && cached.ExpiresAt > DateTimeOffset.UtcNow)
    return cached.Response;

var txId = Guid.NewGuid().ToString("N")[..16];
db.Transactions.Add(new TxRecord { Id = txId, User = db.Tokens[auth], Amount = req!.Amount });
var transferResponse = Results.Ok(new { transaction_id = txId, amount = req.Amount, status = "transferred" });
db.IdempotencyCache[idempotencyKey] = (transferResponse, DateTimeOffset.UtcNow.AddHours(24));
return transferResponse;

